import json
from email.utils import parsedate_to_datetime

CACHEABLE_STATUSES = {200, 203, 204, 206, 301, 404, 410}

def parse_cc(headers):
    for k, v in headers.items():
        if k.lower() == 'cache-control':
            return [d.strip().lower() for d in v.split(',')]
    return []

def get_header(headers, name):
    for k, v in headers.items():
        if k.lower() == name.lower():
            return v
    return None

rows = []
with open('/app/responses.jsonl') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        r = json.loads(line)
        h = r['headers']
        cc = parse_cc(h)

        if 'no-store' in cc:
            rows.append((r['id'], 'false', 0, 'no-store'))
            continue

        has_public = 'public' in cc
        cacheable = r['status'] in CACHEABLE_STATUSES or has_public

        if not cacheable:
            rows.append((r['id'], 'false', 0, 'status-not-cacheable'))
            continue

        # find max-age
        max_age = None
        for d in cc:
            if d.startswith('max-age='):
                try:
                    max_age = int(d.split('=', 1)[1])
                except ValueError:
                    pass

        if max_age is not None:
            rows.append((r['id'], 'true', max_age, 'fresh-max-age'))
            continue

        # try Expires vs Date
        expires = get_header(h, 'expires')
        date = get_header(h, 'date')
        if expires and date:
            try:
                ttl = int((parsedate_to_datetime(expires) - parsedate_to_datetime(date)).total_seconds())
                if ttl > 0:
                    rows.append((r['id'], 'true', ttl, 'expires'))
                    continue
            except Exception:
                pass

        rows.append((r['id'], 'true', 0, 'cacheable-no-ttl'))

with open('/app/cache_report.csv', 'w') as f:
    f.write('id,cacheable,ttl_seconds,reason\n')
    for row in rows:
        f.write(f'{row[0]},{row[1]},{row[2]},{row[3]}\n')
EOF
python3 /app/solve.py && cat /app/cache_report.csv

